<script setup lang="ts">
import {allOptions} from '../../api/options'
import{computed,ref,onMounted,watch}from'vue';import{useRoute}from'vue-router';import{http}from'../../api/http';import{day}from'../../utils/dates';import TrendChart from'../../components/TrendChart.vue';import type {Row} from '../../shared/records'
const route=useRoute(),admin=computed(()=>route.path.startsWith('/admin')),elders=ref<Row[]>([]),sites=ref<Row[]>([]),elderId=ref<number>(),siteId=ref<number>(),period=ref('week'),start=ref(day(-6)),end=ref(day()),report=ref<Row>({totals:{},days:[]}),history=ref<Row[]>([]),overview=ref<Row>({}),trends=ref<Row[]>([]),recommendation=ref<Row>({}),forecasts=ref<Row[]>([]),error=ref(''),pending=ref(false)
const metrics=[['caloriesKcal','能量','kcal'],['proteinGrams','蛋白质','g'],['fatGrams','脂肪','g'],['carbGrams','碳水化合物','g'],['sodiumMg','钠','mg']]
async function load(){pending.value=true;error.value='';try{if(admin.value){const params={dateFrom:start.value,dateTo:end.value,siteId:siteId.value};[overview.value,trends.value,recommendation.value,forecasts.value,report.value]=await Promise.all([http.get<never,any>('/dashboard/overview',{params}),http.get<never,any>('/dashboard/orders-trend',{params}),http.get<never,any>('/dashboard/recommendation-stats',{params}),http.get<never,any>('/dashboard/attendance-forecast',{params}),http.get<never,any>('/dashboard/nutrition-stats',{params})])}else if(elderId.value){report.value=await http.get(`/elders/${elderId.value}/nutrition-report`,{params:{period:period.value,startDate:start.value}});history.value=await http.get(`/elders/${elderId.value}/meal-history`)}}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
onMounted(async()=>{try{if(admin.value)sites.value=(await allOptions('/sites?size=100'));else{elders.value=(await allOptions('/elders?size=100')).filter((v:Row)=>v.approvalStatus==='APPROVED');elderId.value=elders.value[0]?.id}await load()}catch(e){error.value=(e as Error).message}})
watch(()=>[elderId.value,siteId.value,period.value],()=>void load())
function printReport(){window.print()}
</script>
<template><section><p class="eyebrow">记录每一餐</p><h1>{{admin?'运营数据看板':'老人膳食报告'}}</h1><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="toolbar"><el-select v-if="admin" v-model="siteId" filterable clearable placeholder="全部网点" aria-label="统计网点"><el-option v-for="site in sites" :key="site.id" :value="site.id" :label="site.name"/></el-select><el-select v-else v-model="elderId" filterable aria-label="报告老人"><el-option v-for="elder in elders" :key="elder.id" :value="elder.id" :label="elder.name"/></el-select><el-select v-if="!admin" v-model="period" aria-label="报告周期"><el-option value="week" label="周报告"/><el-option value="month" label="月报告"/></el-select><label for="report-start">开始日期</label><el-input id="report-start" v-model="start" type="date"/><template v-if="admin"><label for="report-end">结束日期</label><el-input id="report-end" v-model="end" type="date"/></template><el-button type="primary" :loading="pending" @click="load">查询报告</el-button><el-button @click="printReport">打印报告</el-button></div>
<template v-if="admin"><div class="info-grid"><article v-for="(label,key) in {orderCount:'订单总量',dinerCount:'实际就餐人次',netRevenue:'净收入 元',subsidyAmount:'净补贴 元',refundAmount:'成功退款 元'}" :key="key" class="content-card"><p>{{label}}</p><h2>{{overview[key]??'—'}}</h2></article></div><p>{{overview.scopeNotice}}</p><section class="content-card"><h2>每日订单趋势</h2><TrendChart :labels="trends.map(v=>v.date)" :series="[{name:'全部订单',data:trends.map(v=>Number(v.orderCount))},{name:'有效订单',data:trends.map(v=>Number(v.validCount))}]"/></section><section class="content-card" style="margin-top:24px"><h2>推荐展示与转化</h2><p>有效曝光 {{recommendation.exposureCount??0}} 次；转化 {{recommendation.conversionCount??0}} 次；转化率 {{recommendation.conversionRate==null?'暂无样本':(Number(recommendation.conversionRate)*100).toFixed(2)+'%'}}</p><p>{{recommendation.notice}}</p></section><section v-for="site in forecasts" :key="site.siteId" class="content-card" style="margin-top:24px"><h2>{{site.siteName}} · 实际与预测</h2><TrendChart :labels="[...site.forecast.history].reverse().map((v:Row)=>v.date).concat(site.forecast.points.map((v:Row)=>v.date))" :series="[{name:'实际人数',data:[...site.forecast.history].reverse().map((v:Row)=>Number(v.count)).concat(site.forecast.points.map(()=>null))},{name:'预测人数',data:site.forecast.history.map(()=>null).concat(site.forecast.points.map((v:Row)=>v.count))}]"/></section></template>
<section v-if="admin&&!report.empty" class="content-card" style="margin-top:24px"><h2>已完成餐食的营养构成</h2><TrendChart :labels="['蛋白质','脂肪','碳水化合物']" :series="[{name:'累计克数 g',data:['proteinGrams','fatGrams','carbGrams'].map(k=>report.totals?.[k]==null?null:Number(report.totals[k]))}]" kind="bar"/></section><el-alert :title="report.notice??'只统计本系统已核销或送达餐食的营养估算，不能视为完整每日摄入或医学诊断'" type="info" :closable="false"/><el-empty v-if="report.empty" description="所选周期暂无已核销或送达餐食记录"/><div v-else class="info-grid"><article v-for="[key,label,unit] in metrics" :key="key" class="content-card"><p>{{label}}</p><h2>{{report.totals?.[key!]??'未登记'}} {{report.totals?.[key!]!=null?unit:''}}</h2></article></div><template v-if="!admin&&!report.empty"><p>已记录 {{report.mealCount??0}} 餐；{{report.missingNutrientValues??0}} 项营养值缺失。</p><TrendChart :labels="(report.days??[]).map((v:Row)=>v.date)" :series="[{name:'餐食估算能量 kcal',data:(report.days??[]).map((v:Row)=>v.caloriesKcal==null?null:Number(v.caloriesKcal))}]"/><h2>实际用餐历史</h2><el-table :data="history"><el-table-column prop="mealDate" label="日期"/><el-table-column prop="dishNameSnapshot" label="菜品"/><el-table-column prop="qty" label="份数"/></el-table></template></section></template>
